questionvariables.text:
base:35+5*rand(5);
/* Peak height and dip depth, in steps of 5 yield units (2 to 4 steps each). */
ph:2+rand(3);
pd:2+rand(3);
/* Keep peak and dip far enough apart that their slopes never touch, */
/* so edge-adjacent plots always differ by at most 5. Re-roll both positions. */
sep:2*ph+2*pd-2;
hx:rand(10);
hy:rand(10);
cx:rand(10);
cy:rand(10);
while abs(hx-cx)+abs(hy-cy)<sep do (hx:rand(10),hy:rand(10),cx:rand(10),cy:rand(10));
yield_at(i):=block([x,y,dh,dc],x:mod(i-1,10),y:floor((i-1)/10),
 dh:floor(max(0,2*ph-abs(x-hx)-abs(y-hy))/2),
 dc:floor(max(0,2*pd-abs(x-cx)-abs(y-cy))/2),
 base+5*(dh-dc));
field:makelist(yield_at(i),i,1,100);
field_min:apply(min,field);
field_max:apply(max,field);
field_range:field_max-field_min;
ta:field_range;
statements:[[1,false,"The full-field range could be smaller than my observed range."],[2,true,"Measuring extra plots, in addition to the ones already measured, can never make the observed range smaller."],[3,true,"Measuring plots that are all close together is likely to miss the extremes, because neighbouring yields are similar."],[4,false,"A sample range is equally likely to overestimate or underestimate the full-field range."]];
true_keys:[2,3];
